import {Icon, SegmentedRadioGroup, Text, useTheme, useThemeValue} from '@gravity-ui/uikit';
import type {Theme} from '@gravity-ui/uikit';
import {Display, Moon, Sun} from '@gravity-ui/icons';

export type ThemeSwitcherProps = {
  /** Called with the selected theme; the parent passes it to `ThemeProvider`'s `theme` prop. */
  onUpdate: (theme: Theme) => void;
};

/**
 * Light / dark / system switcher for @gravity-ui/uikit v7.
 *
 * In v7 the theme is controlled by `ThemeProvider`'s `theme` prop, and
 * `useTheme()` only reads it — so the setter comes from the owner of that state.
 * `useThemeValue()` gives the resolved theme (`light` / `dark` / …) when `system` is selected.
 */
export function ThemeSwitcher({onUpdate}: ThemeSwitcherProps) {
  const theme = useTheme();
  const resolvedTheme = useThemeValue();

  return (
    <SegmentedRadioGroup<Theme>
      value={theme}
      onUpdate={onUpdate}
      size="m"
      aria-label="Theme"
      title={theme === 'system' ? `System (${resolvedTheme})` : undefined}
    >
      <SegmentedRadioGroup.Option<Theme> value="light" title="Light">
        <Icon data={Sun} size={16} />
        <Text variant="body-1" style={{marginInlineStart: 6}}>
          Light
        </Text>
      </SegmentedRadioGroup.Option>
      <SegmentedRadioGroup.Option<Theme> value="dark" title="Dark">
        <Icon data={Moon} size={16} />
        <Text variant="body-1" style={{marginInlineStart: 6}}>
          Dark
        </Text>
      </SegmentedRadioGroup.Option>
      <SegmentedRadioGroup.Option<Theme> value="system" title="System">
        <Icon data={Display} size={16} />
        <Text variant="body-1" style={{marginInlineStart: 6}}>
          System
        </Text>
      </SegmentedRadioGroup.Option>
    </SegmentedRadioGroup>
  );
}
EOF
cat > src/useAppTheme.ts <<'EOF'
import {useCallback, useState} from 'react';
import type {Theme} from '@gravity-ui/uikit';

const STORAGE_KEY = 'app-theme';
const KNOWN_THEMES: Theme[] = ['light', 'dark', 'light-hc', 'dark-hc', 'system'];

function readStoredTheme(): Theme {
  try {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    if (stored && KNOWN_THEMES.includes(stored)) {
      return stored;
    }
  } catch {
    // localStorage may be unavailable (privacy mode, SSR) — fall through to the default.
  }
  return 'system';
}

/** App-level theme state that drives `ThemeProvider`'s `theme` prop, persisted in localStorage. */
export function useAppTheme(): [Theme, (theme: Theme) => void] {
  const [theme, setThemeState] = useState<Theme>(readStoredTheme);

  const setTheme = useCallback((next: Theme) => {
    setThemeState(next);
    try {
      window.localStorage.setItem(STORAGE_KEY, next);
    } catch {
      // Ignore persistence failures; the in-memory state still updates.
    }
  }, []);

  return [theme, setTheme];
}
EOF
cat > src/App.tsx <<'EOF'
import {Card, Flex, Text, ThemeProvider, useThemeValue} from '@gravity-ui/uikit';

import {ThemeSwitcher} from './ThemeSwitcher';
import {useAppTheme} from './useAppTheme';

function Content() {
  const resolvedTheme = useThemeValue();

  return (
    <Card view="filled" style={{padding: 'var(--g-spacing-4)'}}>
      <Text as="p" variant="body-2">
        Active theme: <Text variant="code-inline-2">{resolvedTheme}</Text>
      </Text>
    </Card>
  );
}

export function App() {
  const [theme, setTheme] = useAppTheme();

  return (
    <ThemeProvider theme={theme}>
      <Flex direction="column" gap={4} style={{padding: 'var(--g-spacing-6)'}}>
        <Flex alignItems="center" justifyContent="space-between" gap={4} wrap>
          <Text variant="header-1">Theme switcher</Text>
          <ThemeSwitcher onUpdate={setTheme} />
        </Flex>
        <Content />
      </Flex>
    </ThemeProvider>
  );
}
EOF
